    try:
        docs = yaml_docs(path)
    except ValueError as e:
        die(f"{path} is not valid YAML: {e}")
    if len(docs) != 1 or not isinstance(docs[0], dict):
        die(f"{path} must contain exactly one YAML mapping")
    return docs[0]


def as_list(v):
    if v is None:
        return []
    return v if isinstance(v, list) else [v]

