JKW = {"if", "else", "elif", "in", "and", "or", "not", "true", "false", "none", "is", "defined", "undefined", "default", "True", "False", "None", "omit", "item", "inventory_hostname", "hostvars", "groups", "ansible_check_mode", "loop"}


