    if not isinstance(t, dict) or not t.get("_m"):
        continue
    m = short(t["_m"])
    needs = m in ("apt", "package", "service", "systemd", "user") or (m in ("copy", "template", "file") and str(margs(t, t["_m"]).get("dest", margs(t, t["_m"]).get("path", ""))).startswith(tuple(priv)))
