    rep.check(not needs or eff is True, f"task {t.get('name')!r}: needs root (`become: true` on the task or on the play)")

# R7 handlers
hnames = {h.get("name") for h in handlers if isinstance(h, dict)}
notified = set()
for t in tasks:
    if isinstance(t, dict):
